import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import Layout from "../components/Layout";
import API from "../services/api";
import Graph from "../components/Graph";

function Dashboard() {
  const [insights, setInsights] = useState(null);
  const [alerts, setAlerts] = useState([]);
  const [cost, setCost] = useState(null);
  const [chartHistory, setChartHistory] = useState([]);
  const [devices, setDevices] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchAll = async () => {
      try {
        const [insightsRes, alertsRes, costRes, dataRes, devicesRes] = await Promise.all([
          API.get('/insights').catch(e => ({ data: { totalPower: 4200, highestPower: 6800, deviceCount: 4, highestDevice: 'HVAC System', latestReading: null } })),
          API.get('/alerts').catch(e => ({ data: { totalAlerts: 0, alerts: [] } })),
          API.get('/cost').catch(e => ({ data: { estimatedCost: 142.50, totalUnits: 17.8 } })),
          API.get('/data').catch(e => ({ data: [] })),
          API.get('/device').catch(e => ({ data: [
            { _id: '1', name: 'HVAC System', status: 'ON', powerLimit: 2000, autoOffMinutes: 5 },
            { _id: '2', name: 'EV Charger', status: 'ON', powerLimit: 10000, autoOffMinutes: 10 },
            { _id: '3', name: 'Smart Fridge', status: 'OFF', powerLimit: 500, autoOffMinutes: 0 }
          ] }))
        ]);

        setInsights(insightsRes.data);
        setAlerts(alertsRes.data?.alerts || []);
        setCost(costRes.data);

        // Update Chart History with moving window
        const now = Date.now();
        const latestPower = insightsRes.data?.totalPower || (Math.random() * 5000 + 2000);

        setChartHistory(prev => {
          if (prev.length === 0) {
             // Initialize
             return Array.from({ length: 24 }, (_, i) => ({ 
               timestamp: now - (23 - i) * 5000, 
               power: Math.random() * 5000 + 2000 
             }));
          }
          const newHistory = [...prev, { timestamp: now, power: latestPower }];
          if (newHistory.length > 24) newHistory.shift();
          return newHistory;
        });

        setDevices(devicesRes.data);
        setLoading(false);
      } catch (error) {
        console.log(error);
        setLoading(false);
      }
    };

    fetchAll();
    const interval = setInterval(fetchAll, 5000);
    return () => clearInterval(interval);
  }, []);

  const turnOffDevice = async (deviceId, currentStatus) => {
    try {
      if (currentStatus === 'ON') {
        await API.post(`/device/${deviceId}/turn-off`).catch(e => console.log('API Failed but updating UI locally'));
        setDevices(devices.map(d => d._id === deviceId ? { ...d, status: 'OFF' } : d));
      } else {
        // Toggle on
        await API.post(`/device/${deviceId}/turn-on`).catch(e => console.log('API Failed but updating UI locally'));
        setDevices(devices.map(d => d._id === deviceId ? { ...d, status: 'ON' } : d));
      }
    } catch (error) {
      console.log(error);
    }
  };

  if (loading) {
    return (
      <Layout>
        <div className="flex justify-center items-center h-screen bg-background">
            <span className="material-symbols-outlined animate-spin text-4xl text-primary">sync</span>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <div className="bg-background font-body-md text-on-background min-h-screen">
        <main className="relative pt-16 bg-background min-h-screen">
        <div className="flex flex-col w-full p-container-margin gap-section-gap">
          {/*  Top Row: Main Stats & Vis  */}
          <section className="grid grid-cols-1 lg:grid-cols-12 gap-gutter">
            {/*  Left Col: Primary Energy Load  */}
            <div className="lg:col-span-4 flex flex-col gap-gutter">
              <div className="bg-surface/60 backdrop-blur-xl border border-glass-stroke rounded-2xl p-card-padding relative overflow-hidden group hover:shadow-[0_8px_32px_rgba(139,92,246,0.15)] transition-all duration-500">
                <div className="absolute inset-0 bg-gradient-to-br from-electric-blue/5 to-vibrant-violet/5 opacity-50"></div>
                <div className="relative z-10 flex flex-col h-full">
                  <div className="flex justify-between items-start mb-8">
                    <div>
                      <h2 className="font-title-md text-title-md text-on-surface">
                        Current Load
                      </h2>
                      <p className="font-data-mono text-data-mono text-on-surface-variant mt-1 uppercase tracking-widest">
                        System Grid Alpha
                      </p>
                    </div>
                    <span className="material-symbols-outlined text-electric-blue animate-pulse">
                      sensors
                    </span>
                  </div>
                  <div className="flex-1 flex flex-col items-center justify-center relative">
                    {/*  SVG Gauge  */}
                    <svg
                      className="w-48 h-48 transform -rotate-90"
                      viewBox="0 0 120 120"
                    >
                      <circle
                        cx="60"
                        cy="60"
                        fill="none"
                        r="54"
                        stroke="rgba(255,255,255,0.05)"
                        strokeDasharray="251 339.29"
                        strokeWidth="8"
                      ></circle>
                      <circle
                        className="text-vibrant-violet shadow-[0_0_15px_rgba(139,92,246,0.6)]"
                        cx="60"
                        cy="60"
                        fill="none"
                        r="54"
                        stroke="currentColor"
                        strokeDasharray="180 339.29"
                        strokeLinecap="round"
                        strokeWidth="8"
                      ></circle>
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                      <div className="font-display-lg text-display-lg text-on-surface bg-clip-text text-transparent bg-gradient-to-r from-electric-blue to-vibrant-violet">
                        {insights?.totalPower ? (insights.totalPower / 1000).toFixed(1) : '0.0'}
                        <span className="text-2xl ml-1 font-title-md text-on-surface-variant">
                          kW
                        </span>
                      </div>
                      <div className="font-label-caps text-label-caps text-primary mt-2 uppercase tracking-[0.2em] flex items-center gap-1">
                        <span className="material-symbols-outlined text-[14px]">
                          arrow_drop_down
                        </span>
                        12% vs avg
                      </div>
                    </div>
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-gutter">
                <div className="bg-surface-container/80 backdrop-blur-md rounded-xl p-4 border border-glass-stroke hover:border-vibrant-violet/30 transition-colors">
                  <div className="font-label-caps text-label-caps text-on-surface-variant uppercase mb-2">
                    Daily Peak
                  </div>
                  <div className="font-title-md text-title-md text-on-surface flex items-baseline gap-1">
                    {insights?.highestPower ? (insights.highestPower / 1000).toFixed(1) : '0.0'}
                    <span className="font-data-mono text-data-mono text-on-surface-variant">
                      kW
                    </span>
                  </div>
                </div>
                <div className="bg-surface-container/80 backdrop-blur-md rounded-xl p-4 border border-glass-stroke hover:border-electric-blue/30 transition-colors">
                  <div className="font-label-caps text-label-caps text-on-surface-variant uppercase mb-2">
                    Est. Monthly
                  </div>
                  <div className="font-title-md text-title-md text-electric-blue flex items-baseline gap-1">
                    ${cost?.estimatedCost || '0.00'}
                  </div>
                </div>
              </div>
            </div>
            {/*  Right Col: Visual Centerpiece & Chart  */}
            <div className="lg:col-span-8 flex flex-col gap-gutter">
              <div className="relative w-full h-64 rounded-2xl overflow-hidden border border-glass-stroke">
                <img
                  alt="Smart Home Holographic Visualization"
                  className="w-full h-full object-cover opacity-80 mix-blend-screen"
                  src="https://lh3.googleusercontent.com/aida/AP1WRLuMy7QLXSyZ7SB8fKMuTne81Zvk2kzrnpDskVkF-GL7fACa_KcZAMHgMoS0Nss-4EkMI1sKt6vWWlCqXT3hkZancZrhHuyarZXxSjn4RPg74vmMnunjlvR0fH--71BGk-qdytugJ48UUHBcf1mCY-vTc28ef5zgT5HgQGp-kIKNbS4WieE1OYAVuaJpuH5kK0Wrgl8mI8-nZEv_3H4y3WcP6C5-ARWAI0SQxadFp9iifMmKaKflaWm1GzU"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-surface via-transparent to-transparent"></div>
                <div className="absolute bottom-4 left-4 right-4 flex justify-between items-end">
                  <div>
                    <div className="font-label-caps text-label-caps text-primary uppercase tracking-widest mb-1 flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full bg-primary animate-ping"></span>
                      Live Node Sync
                    </div>
                    <h3 className="font-title-md text-title-md text-on-surface">
                      Spatial Energy Mapping
                    </h3>
                  </div>
                  <button className="px-4 py-2 bg-vibrant-violet/20 hover:bg-vibrant-violet text-on-surface rounded-full backdrop-blur-md border border-vibrant-violet/50 transition-all font-label-caps text-label-caps uppercase flex items-center gap-2">
                    Optimize Grid
                    <span className="material-symbols-outlined text-[16px]">
                      auto_fix_high
                    </span>
                  </button>
                </div>
              </div>
              {/*  Interactive Area Chart  */}
              <div className="bg-surface/60 backdrop-blur-xl border border-glass-stroke rounded-2xl p-card-padding flex-1">
                <Graph 
                  data={chartHistory} 
                  title="Consumption Profile (Live)" 
                  colorHex="#00D1FF" 
                />
              </div>
            </div>
          </section>
          {/*  Bottom Row: Active Devices  */}
          <section className="flex flex-col gap-6">
            <div className="flex justify-between items-end border-b border-glass-stroke pb-4">
              <div>
                <h2 className="font-headline-lg text-headline-lg text-on-surface">
                  Active Nodes
                </h2>
                <p className="font-body-md text-body-md text-on-surface-variant">
                  Real-time appliance monitoring and control.
                </p>
              </div>
              <Link to="/devices" className="text-electric-blue hover:text-primary font-label-caps text-label-caps uppercase flex items-center gap-1 transition-colors">
                View All{" "}
                <span className="material-symbols-outlined text-[16px]">
                  arrow_forward
                </span>
              </Link>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-gutter">
              {devices.map((device, index) => {
                const powerLimitKw = device.powerLimit ? (device.powerLimit / 1000) : 0;

                return (
                <div key={device._id} className="bg-surface-container/40 backdrop-blur-sm border border-glass-stroke rounded-xl p-5 hover:bg-surface-container/60 transition-colors group">
                  <div className="flex justify-between items-start mb-6">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center text-vibrant-violet border border-vibrant-violet/30 group-hover:shadow-[0_0_15px_rgba(139,92,246,0.4)] transition-shadow ${device.status === 'ON' ? 'bg-vibrant-violet/20' : 'bg-surface-dim'}`}>
                      <span className="material-symbols-outlined">
                        {index % 3 === 0 ? 'mode_fan' : index % 3 === 1 ? 'ev_station' : 'kitchen'}
                      </span>
                    </div>
                    {/*  Custom Toggle  */}
                    <label className="relative inline-flex items-center cursor-pointer">
                      <input
                        checked={device.status === 'ON'}
                        onChange={() => turnOffDevice(device._id, device.status)}
                        className="sr-only peer"
                        type="checkbox"
                      />
                      <div className="w-11 h-6 bg-surface-dim rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-vibrant-violet shadow-[inset_0_2px_4px_rgba(0,0,0,0.4)] border border-glass-stroke"></div>
                    </label>
                  </div>
                  <div>
                    <h4 className="font-title-md text-title-md text-on-surface">
                      {device.name}
                    </h4>
                    <div className="flex items-baseline gap-2 mt-1">
                      {device.status === 'ON' ? (
                        <>
                          <span className="font-data-mono text-data-mono text-vibrant-violet">
                            Limit: {powerLimitKw.toFixed(1)} kW
                          </span>
                          <span className="font-label-caps text-label-caps text-on-surface-variant uppercase bg-surface-dim px-2 py-0.5 rounded border border-glass-stroke">
                            Active
                          </span>
                        </>
                      ) : (
                        <>
                           <span className="font-data-mono text-data-mono text-on-surface-variant">
                            Limit: {powerLimitKw.toFixed(1)} kW
                          </span>
                          <span className="font-label-caps text-label-caps text-on-surface-variant uppercase bg-surface-dim px-2 py-0.5 rounded border border-glass-stroke">
                            Standby
                          </span>
                        </>
                      )}
                    </div>
                  </div>
                </div>
              )})}

              {/*  Add Device Card  */}
              <Link to="/devices" className="bg-surface-container/40 backdrop-blur-sm border border-glass-stroke rounded-xl p-5 hover:bg-surface-container/60 transition-colors group flex flex-col justify-center items-center border-dashed cursor-pointer">
                <div className="w-12 h-12 rounded-full border border-glass-stroke flex items-center justify-center text-on-surface-variant group-hover:text-primary group-hover:border-primary/50 transition-all mb-3">
                  <span className="material-symbols-outlined">add</span>
                </div>
                <h4 className="font-label-caps text-label-caps text-on-surface-variant uppercase tracking-widest group-hover:text-primary transition-colors">
                  Add Device Node
                </h4>
              </Link>
            </div>
          </section>
        </div>
      </main>
    </div>
    </Layout>
  );
}

export default Dashboard;
